using System.Threading.Tasks;\nusing Xunit;\nusing Microsoft.Playwright;\n\nnamespace TestProject.Ui.Tests\n{\n    public class UiTests : IAsyncLifetime\n    {\n        private IPlaywright _playwright;\n        private IBrowser _browser;\n        private IPage _page;\n\n        public async Task InitializeAsync()\n        {\n            _playwright = await Playwright.CreateAsync();\n            _browser = await _playwright.Chromium.LaunchAsync(new BrowserTypeLaunchOptions { Headless = true });\n            _page = await _browser.NewPageAsync();\n        }\n\n        public async Task DisposeAsync()\n        {\n            await _page.CloseAsync();\n            await _browser.CloseAsync();\n            _playwright.Dispose();\n        }\n\n        [Fact]\n        public async Task CreatedItem_ShouldBeVisible()\n        {\n            await _page.GotoAsync(\"https://ui.example.com\");\n            await _page.ClickAsync(\"#new-item-button\");\n            await _page.FillAsync(\"#item-name\", \"Test Item\");\n            await _page.FillAsync(\"#item-description\", \"This is a test item\");\n            await _page.ClickAsync(\"#submit-button\");\n\n            var newItem = await _page.QuerySelectorAsync(\"text=Test Item\");\n            Assert.NotNull(newItem);\n        }\n    }\n}\n